-- Shopify-linked stock: a product with shopifyKey is taken out of stock when that store sells it,
-- and put back when the order is cancelled. Key = store|title|variant, normalised by stockShopify.shopifyKeyOf
-- (lowercase; in each " / " part of the variant the words are sorted, hyphens split, number-only words dropped).
ALTER TABLE "StockProduct" ADD COLUMN "shopifyKey" TEXT;
CREATE UNIQUE INDEX "StockProduct_shopifyKey_key" ON "StockProduct"("shopifyKey");

-- Cheetah's blank T-shirts (167 variants), kept only in the CHEETAH warehouse.
ON CONFLICT DO NOTHING;

SELECT w."id", p."id", 0, (upper(w."name") = 'CHEETAH')
FROM "StockProduct" p CROSS JOIN "StockWarehouse" w
WHERE p."shopifyKey" LIKE 'cheetah|%'
ON CONFLICT DO NOTHING;

ON CONFLICT ("key") DO UPDATE SET "value" = "AppConfig"."value" || '["T-Shirt"]'::jsonb, "updatedAt" = now()
WHERE NOT ("AppConfig"."value" @> '["T-Shirt"]'::jsonb);
